  j constant jsonb := $j$[
{"id":"7b021b7c-fe42-472e-b4f3-fc2e768a439c","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"es","slug":"torta-de-chocolate","public_path":"/torta-de-chocolate","source_url":null,"title":"Torta de chocolate","excerpt":"Torta de chocolate casera: bizcocho húmedo y esponjoso hecho con cacao, horneado en un molde de 22 cm y cubierto con ganache brillante. Para 8 porciones.","summary":"Esta torta de chocolate es un bizcocho de miga fina y húmeda que se hace mezclando por separado los ingredientes secos (harina, azúcar, cacao y polvo de hornear) y los líquidos (huevos, leche, aceite y vainilla), uniéndolos con un batidor y horneando la masa en un molde de 22 cm. Se cubre con una ganache de chocolate y crema de leche.\n\nLleva 20 minutos de preparación, 45 de cocción y 1 hora y 25 minutos de enfriado y reposo. Rinde 8 porciones.","category":"Postres","difficulty":"Fácil","course":"Postre","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["torta de chocolate","receta de torta de chocolate casera","torta de chocolate húmeda","torta de chocolate con ganache","bizcocho de chocolate","cómo hacer torta de chocolate","torta de cacao"],"ingredients":[{"name":"harina de trigo","amount":"200","unit":"g","group":"Para la torta"},{"name":"azúcar","amount":"200","unit":"g","group":"Para la torta"},{"name":"cacao en polvo sin azúcar","amount":"60","unit":"g","group":"Para la torta"},{"name":"polvo de hornear","amount":"2","unit":"cucharadita","group":"Para la torta"},{"name":"sal","amount":"1","unit":"pizca","group":"Para la torta"},{"name":"huevos grandes","amount":"3","unit":"","group":"Para la torta"},{"name":"leche entera","amount":"240","unit":"ml","group":"Para la torta"},{"name":"aceite vegetal","amount":"120","unit":"ml","group":"Para la torta"},{"name":"extracto de vainilla","amount":"1","unit":"cucharadita","group":"Para la torta"},{"name":"mantequilla (para el molde)","amount":"10","unit":"g","group":"Para la torta"},{"name":"chocolate semiamargo","amount":"150","unit":"g","group":"Para la cobertura"},{"name":"crema de leche","amount":"150","unit":"ml","group":"Para la cobertura"}],"steps":[{"title":"Prepara los ingredientes","content":"Ten a mano 200 g de harina, 200 g de azúcar, 60 g de cacao en polvo, 2 cucharaditas de polvo de hornear, 3 huevos, 240 ml de leche, 120 ml de aceite, 1 cucharadita de vainilla, 150 g de chocolate y 150 ml de crema de leche. Precalienta el horno a 180 °C, unta con mantequilla un molde redondo de 22 cm y enharínalo con un poco de la harina, quitando el exceso.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Torta de chocolate: Prepara los ingredientes"},{"title":"Mezcla los ingredientes secos","content":"Tamiza en un bol grande los 200 g de harina, los 200 g de azúcar, los 60 g de cacao, el polvo de hornear y una pizca de sal. Mezcla con un batidor de varillas.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Torta de chocolate: Mezcla los ingredientes secos"},{"title":"Bate los líquidos","content":"En otro bol bate 3 huevos con 240 ml de leche, 120 ml de aceite y 1 cucharadita de vainilla durante 1 minuto, hasta que la mezcla quede uniforme.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Torta de chocolate: Bate los líquidos"},{"title":"Une las dos mezclas","content":"Vierte los líquidos sobre los ingredientes secos y bate hasta obtener una masa lisa, fluida y sin grumos. No batas de más, para que la torta no quede dura.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Torta de chocolate: Une las dos mezclas"},{"title":"Llena el molde","content":"Pasa la masa al molde preparado, nivélala con una espátula y golpea el molde con suavidad contra la mesa para sacar las burbujas grandes.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Torta de chocolate: Llena el molde"},{"title":"Hornea la torta","content":"Hornea a 180 °C de 35 a 40 minutos, hasta que un palillo clavado en el centro salga limpio o con unas migas húmedas. No abras el horno durante los primeros 25 minutos.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Torta de chocolate: Hornea la torta"},{"title":"Enfría y desmolda","content":"Deja la torta 10 minutos en el molde, desmóldala sobre una rejilla y deja que se enfríe por completo, al menos 1 hora.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Torta de chocolate: Enfría y desmolda"},{"title":"Cubre y sirve","content":"Calienta 150 ml de crema de leche hasta que empiece a hervir y viértela sobre 150 g de chocolate picado. Espera 2 minutos y mezcla hasta que quede brillante. Deja templar 10 minutos, vierte la ganache sobre la torta fría y déjala reposar 15 minutos antes de cortarla.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Torta de chocolate: Cubre y sirve"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Torta de chocolate"}],"notes":"Mide los ingredientes con balanza: una taza de harina de más deja la torta seca. Tamiza el cacao para que no queden grumos. La masa queda líquida; es normal, y es lo que da una miga húmeda. Cada horno es distinto: empieza a revisar a los 35 minutos. Si la ganache se espesa demasiado, caliéntala 10 segundos en el microondas. Contiene gluten, huevo y lácteos. Se conserva 3 días tapada a temperatura ambiente o 5 en la nevera; sácala 20 minutos antes de servirla.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 porción (1/8 de la torta, unos 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 8 porciones: 200 g de harina, 200 g de azúcar, 60 g de cacao, 9 g de polvo de hornear, 0,4 g de sal, 150 g de huevo, 245 g de leche entera, 110 g de aceite de soya, 4 g de vainilla, 10 g de mantequilla (se cuenta toda aunque parte quede en el molde), 150 g de chocolate semiamargo y 143 g de crema de leche.","note":"Estimación por porción. Varía con el tamaño de la porción y la marca del chocolate.","inputs":[{"fdc_id":"169761","description":"Wheat flour, white, all-purpose, enriched, bleached (200 g)","grams":200,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.152,"fiber_g":2.7,"sodium_mg":2}},{"fdc_id":"169655","description":"Sugars, granulated (200 g)","grams":200,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"169593","description":"Cocoa, dry powder, unsweetened (60 g)","grams":60,"per100":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":33.2,"sodium_mg":21}},{"fdc_id":"18369","description":"Leavening agents, baking powder, double-acting, sodium aluminum sulfate (2 cucharaditas ≈ 9 g)","grams":9,"per100":{"calories":53,"protein_g":0,"carbs_g":27.7,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sodium_mg":10600}},{"fdc_id":"173468","description":"Salt, table (una pizca ≈ 0,4 g)","grams":0.4,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh (3 huevos grandes ≈ 150 g)","grams":150,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"171265","description":"Milk, whole, 3.25% milkfat (240 ml ≈ 245 g)","grams":245,"per100":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.865,"fiber_g":0,"sodium_mg":43}},{"fdc_id":"172336","description":"Oil, soybean, salad or cooking (120 ml ≈ 110 g)","grams":110,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":15.65,"fiber_g":0,"sodium_mg":0}},{"fdc_id":"173471","description":"Vanilla extract (1 cucharadita ≈ 4 g)","grams":4,"per100":{"calories":288,"protein_g":0.06,"carbs_g":12.65,"fat_g":0.06,"saturated_fat_g":0.016,"fiber_g":0,"sodium_mg":9}},{"fdc_id":"173430","description":"Butter, salted (10 g para engrasar el molde; se cuenta todo)","grams":10,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":51.368,"fiber_g":0,"sodium_mg":643}},{"fdc_id":"170273","description":"Candies, chocolate, dark, 45-59% cacao solids (150 g de chocolate semiamargo)","grams":150,"per100":{"calories":546,"protein_g":4.88,"carbs_g":61.17,"fat_g":31.28,"saturated_fat_g":18.5,"fiber_g":7,"sodium_mg":24}},{"fdc_id":"170859","description":"Cream, fluid, heavy whipping (150 ml ≈ 143 g)","grams":143,"per100":{"calories":340,"protein_g":2.84,"carbs_g":2.73,"fat_g":36.08,"saturated_fat_g":22.8,"fiber_g":0,"sodium_mg":34}}]},"seo":{"title":"Torta de chocolate casera, húmeda y con ganache | Manual de Cocina","description":"Torta de chocolate casera: bizcocho húmedo con cacao, horneado en molde de 22 cm y cubierto con ganache brillante. Para 8 porciones. Paso a paso con fotos.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"¿Por qué la masa de la torta queda tan líquida?","a":"Porque lleva más líquido que un bizcocho común: la leche y el aceite dan una miga húmeda. Es normal y se asienta al hornear."},{"q":"¿Cómo sé que la torta ya está lista?","a":"Clava un palillo en el centro: debe salir limpio o con unas migas húmedas, no con masa cruda. La superficie debe volver a subir al presionarla suavemente."},{"q":"¿Se puede hacer sin ganache?","a":"Sí. Puedes servirla sola o espolvoreada con azúcar glas. La ganache le da humedad y brillo, pero la torta es buena sin ella."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"c3d8a147-9db5-5e05-9a41-6ddb6ff4e422","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"de","slug":"schokoladenkuchen-mit-ganache","public_path":"/de/schokoladenkuchen-mit-ganache","source_url":null,"title":"Schokoladenkuchen mit Ganache","excerpt":"Saftiger Schokoladenkuchen mit Kakao aus der 22-cm-Form, überzogen mit glänzender Schokoladenganache. 8 Portionen.","summary":"Dieser Schokoladenkuchen hat eine feine, saftige Krume. Trockene (Mehl, Zucker, Kakao, Backpulver) und flüssige Zutaten (Eier, Milch, Öl, Vanille) werden getrennt gemischt, mit dem Schneebesen verbunden und in einer 22-cm-Form gebacken. Zum Schluss kommt eine Ganache aus Schokolade und Sahne darüber.\n\nEr braucht 20 Minuten Vorbereitung, 45 Minuten Backzeit und 1 Stunde 25 Minuten zum Abkühlen und Ruhen. Ergibt 8 Portionen.","category":"Desserts","difficulty":"Einfach","course":"Dessert","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["Schokoladenkuchen","Schokoladenkuchen Rezept","saftiger Schokoladenkuchen","Schokoladenkuchen mit Ganache","Schokokuchen selber machen","Kakaokuchen","Rührkuchen mit Schokolade"],"ingredients":[{"name":"Weizenmehl","amount":"200","unit":"g","group":"Für den Kuchen"},{"name":"Zucker","amount":"200","unit":"g","group":"Für den Kuchen"},{"name":"ungesüßtes Kakaopulver","amount":"60","unit":"g","group":"Für den Kuchen"},{"name":"Backpulver","amount":"2","unit":"Teelöffel","group":"Für den Kuchen"},{"name":"Salz","amount":"1","unit":"Prise","group":"Für den Kuchen"},{"name":"große Eier","amount":"3","unit":"","group":"Für den Kuchen"},{"name":"Vollmilch","amount":"240","unit":"ml","group":"Für den Kuchen"},{"name":"Pflanzenöl","amount":"120","unit":"ml","group":"Für den Kuchen"},{"name":"Vanilleextrakt","amount":"1","unit":"Teelöffel","group":"Für den Kuchen"},{"name":"Butter (für die Form)","amount":"10","unit":"g","group":"Für den Kuchen"},{"name":"Zartbitterschokolade","amount":"150","unit":"g","group":"Für den Überzug"},{"name":"Sahne","amount":"150","unit":"ml","group":"Für den Überzug"}],"steps":[{"title":"Zutaten vorbereiten","content":"200 g Mehl, 200 g Zucker, 60 g Kakao, 2 Teelöffel Backpulver, 3 Eier, 240 ml Milch, 120 ml Öl, 1 Teelöffel Vanille, 150 g Schokolade und 150 ml Sahne bereitstellen. Den Backofen auf 180 °C vorheizen, eine runde 22-cm-Form mit Butter einfetten und mit etwas Mehl ausstäuben, überschüssiges Mehl entfernen.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Schokoladenkuchen mit Ganache: Zutaten vorbereiten"},{"title":"Trockene Zutaten mischen","content":"200 g Mehl, 200 g Zucker, 60 g Kakao, das Backpulver und eine Prise Salz in eine große Schüssel sieben und mit dem Schneebesen mischen.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Schokoladenkuchen mit Ganache: Trockene Zutaten mischen"},{"title":"Flüssige Zutaten verrühren","content":"In einer zweiten Schüssel 3 Eier mit 240 ml Milch, 120 ml Öl und 1 Teelöffel Vanille 1 Minute verrühren, bis alles gleichmäßig ist.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Schokoladenkuchen mit Ganache: Flüssige Zutaten verrühren"},{"title":"Beide Mischungen verbinden","content":"Die flüssigen Zutaten zu den trockenen gießen und zu einem glatten, flüssigen, klumpenfreien Teig verrühren. Nicht zu lange rühren, damit der Kuchen nicht zäh wird.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Schokoladenkuchen mit Ganache: Beide Mischungen verbinden"},{"title":"Form füllen","content":"Den Teig in die vorbereitete Form geben, mit einem Spatel glattstreichen und die Form leicht auf den Tisch klopfen, um große Luftblasen zu entfernen.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Schokoladenkuchen mit Ganache: Form füllen"},{"title":"Kuchen backen","content":"Bei 180 °C 35 bis 40 Minuten backen, bis ein in die Mitte gestochener Holzspieß sauber oder mit feuchten Krümeln herauskommt. In den ersten 25 Minuten den Ofen nicht öffnen.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Schokoladenkuchen mit Ganache: Kuchen backen"},{"title":"Abkühlen und stürzen","content":"Den Kuchen 10 Minuten in der Form lassen, auf ein Gitter stürzen und vollständig abkühlen lassen, mindestens 1 Stunde.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Schokoladenkuchen mit Ganache: Abkühlen und stürzen"},{"title":"Überziehen und servieren","content":"150 ml Sahne bis kurz vor dem Kochen erhitzen und über 150 g gehackte Schokolade gießen. 2 Minuten warten und glatt rühren, bis die Ganache glänzt. 10 Minuten abkühlen lassen, über den kalten Kuchen gießen und 15 Minuten ruhen lassen, bevor er angeschnitten wird.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Schokoladenkuchen mit Ganache: Überziehen und servieren"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Schokoladenkuchen mit Ganache"}],"notes":"Die Zutaten mit der Waage abwiegen: Zu viel Mehl macht den Kuchen trocken. Den Kakao sieben, damit keine Klümpchen entstehen. Der Teig ist flüssig; das ist normal und sorgt für eine saftige Krume. Jeder Ofen ist anders: ab 35 Minuten prüfen. Wird die Ganache zu fest, 10 Sekunden in der Mikrowelle erwärmen. Enthält Gluten, Ei und Milch. Abgedeckt hält sich der Kuchen 3 Tage bei Raumtemperatur oder 5 Tage im Kühlschrank; 20 Minuten vor dem Servieren herausnehmen.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 Portion (1/8 des Kuchens, etwa 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 8 Portionen geteilt: 200 g Mehl, 200 g Zucker, 60 g Kakao, 9 g Backpulver, 0,4 g Salz, 150 g Ei, 245 g Vollmilch, 110 g Sojaöl, 4 g Vanille, 10 g Butter (alles gezählt, auch wenn ein Teil in der Form bleibt), 150 g Zartbitterschokolade und 143 g Sahne.","note":"Schätzung pro Portion. Je nach Stückgröße und Schokoladenmarke unterschiedlich."},"seo":{"title":"Saftiger Schokoladenkuchen mit Ganache selber backen | Manual de Cocina","description":"Schokoladenkuchen: saftiger Kakaokuchen aus der 22-cm-Form mit glänzender Ganache. 8 Portionen. Schritt für Schritt mit Fotos.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Warum ist der Teig so flüssig?","a":"Er enthält mehr Flüssigkeit als ein normaler Rührteig: Milch und Öl sorgen für eine saftige Krume. Das ist normal; der Teig setzt sich beim Backen."},{"q":"Woran erkenne ich, dass der Kuchen fertig ist?","a":"Einen Holzspieß in die Mitte stechen: Er soll sauber oder mit feuchten Krümeln herauskommen, nicht mit rohem Teig. Die Oberfläche federt beim leichten Drücken zurück."},{"q":"Geht der Kuchen auch ohne Ganache?","a":"Ja. Er schmeckt pur oder mit Puderzucker. Die Ganache gibt Saftigkeit und Glanz, aber der Kuchen ist auch ohne gut."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"56d72aeb-e831-57cf-9276-3b84b0d1e03d","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"en","slug":"chocolate-cake-with-ganache","public_path":"/en/chocolate-cake-with-ganache","source_url":null,"title":"Chocolate Cake with Ganache","excerpt":"Moist homemade chocolate cake made with cocoa, baked in a 22 cm pan and covered with glossy chocolate ganache. Serves 8.","summary":"This chocolate cake has a fine, moist crumb. The dry ingredients (flour, sugar, cocoa, baking powder) and the liquids (eggs, milk, oil, vanilla) are mixed separately, combined with a whisk and baked in a 22 cm pan. It is covered with a ganache of chocolate and cream.\n\nIt takes 20 minutes of prep, 45 of baking and 1 hour 25 minutes of cooling and resting. It serves 8.","category":"Desserts","difficulty":"Easy","course":"Dessert","cuisine":"International","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["chocolate cake","homemade chocolate cake recipe","moist chocolate cake","chocolate cake with ganache","chocolate sponge cake","how to make chocolate cake","cocoa cake"],"ingredients":[{"name":"all-purpose flour","amount":"200","unit":"g","group":"For the cake"},{"name":"sugar","amount":"200","unit":"g","group":"For the cake"},{"name":"unsweetened cocoa powder","amount":"60","unit":"g","group":"For the cake"},{"name":"baking powder","amount":"2","unit":"teaspoon","group":"For the cake"},{"name":"salt","amount":"1","unit":"pinch","group":"For the cake"},{"name":"large eggs","amount":"3","unit":"","group":"For the cake"},{"name":"whole milk","amount":"240","unit":"ml","group":"For the cake"},{"name":"vegetable oil","amount":"120","unit":"ml","group":"For the cake"},{"name":"vanilla extract","amount":"1","unit":"teaspoon","group":"For the cake"},{"name":"butter (for the pan)","amount":"10","unit":"g","group":"For the cake"},{"name":"semisweet chocolate","amount":"150","unit":"g","group":"For the topping"},{"name":"heavy cream","amount":"150","unit":"ml","group":"For the topping"}],"steps":[{"title":"Prepare the ingredients","content":"Have ready 200 g flour, 200 g sugar, 60 g cocoa powder, 2 teaspoons baking powder, 3 eggs, 240 ml milk, 120 ml oil, 1 teaspoon vanilla, 150 g chocolate and 150 ml heavy cream. Preheat the oven to 180 °C, grease a 22 cm round pan with butter and dust it with a little of the flour, tapping out the excess.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Chocolate Cake with Ganache: Prepare the ingredients"},{"title":"Mix the dry ingredients","content":"Sift the 200 g flour, 200 g sugar, 60 g cocoa, baking powder and a pinch of salt into a large bowl. Mix with a whisk.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Chocolate Cake with Ganache: Mix the dry ingredients"},{"title":"Whisk the liquids","content":"In another bowl, whisk 3 eggs with 240 ml milk, 120 ml oil and 1 teaspoon vanilla for 1 minute, until uniform.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Chocolate Cake with Ganache: Whisk the liquids"},{"title":"Combine the two mixtures","content":"Pour the liquids over the dry ingredients and whisk into a smooth, fluid batter with no lumps. Do not overmix, or the cake will turn tough.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Chocolate Cake with Ganache: Combine the two mixtures"},{"title":"Fill the pan","content":"Pour the batter into the prepared pan, level it with a spatula and tap the pan gently on the counter to release large air bubbles.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Chocolate Cake with Ganache: Fill the pan"},{"title":"Bake the cake","content":"Bake at 180 °C for 35 to 40 minutes, until a toothpick inserted in the center comes out clean or with a few moist crumbs. Do not open the oven during the first 25 minutes.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Chocolate Cake with Ganache: Bake the cake"},{"title":"Cool and unmold","content":"Leave the cake in the pan for 10 minutes, turn it out onto a rack and let it cool completely, at least 1 hour.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Chocolate Cake with Ganache: Cool and unmold"},{"title":"Cover and serve","content":"Heat 150 ml cream until it just starts to boil and pour it over 150 g chopped chocolate. Wait 2 minutes and stir until glossy. Let it cool for 10 minutes, pour the ganache over the cold cake and let it set for 15 minutes before cutting.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Chocolate Cake with Ganache: Cover and serve"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Chocolate Cake with Ganache"}],"notes":"Weigh the ingredients: a little too much flour makes the cake dry. Sift the cocoa so there are no lumps. The batter is thin; that is normal and gives a moist crumb. Every oven is different: start checking at 35 minutes. If the ganache gets too thick, warm it for 10 seconds in the microwave. Contains gluten, egg and dairy. It keeps for 3 days covered at room temperature or 5 days in the fridge; take it out 20 minutes before serving.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 serving (1/8 of the cake, about 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 8 servings: 200 g flour, 200 g sugar, 60 g cocoa, 9 g baking powder, 0.4 g salt, 150 g egg, 245 g whole milk, 110 g soybean oil, 4 g vanilla, 10 g butter (all of it counted even though some stays in the pan), 150 g semisweet chocolate and 143 g heavy cream.","note":"Estimate per serving. It varies with the size of the slice and the brand of chocolate."},"seo":{"title":"Moist Chocolate Cake with Ganache, Homemade | Manual de Cocina","description":"Homemade chocolate cake: moist cocoa sponge baked in a 22 cm pan and topped with glossy ganache. Serves 8. Step by step with photos.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Why is the cake batter so thin?","a":"It has more liquid than a regular cake batter: the milk and oil give a moist crumb. This is normal and it sets as it bakes."},{"q":"How do I know the cake is done?","a":"Insert a toothpick in the center: it should come out clean or with a few moist crumbs, not raw batter. The surface should spring back when gently pressed."},{"q":"Can I make it without the ganache?","a":"Yes. You can serve it plain or dusted with powdered sugar. The ganache adds moisture and shine, but the cake is good without it."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"128955b4-2147-5478-b7c5-6432620208a0","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"fr","slug":"gateau-au-chocolat-avec-ganache","public_path":"/fr/gateau-au-chocolat-avec-ganache","source_url":null,"title":"Gâteau au chocolat avec ganache","excerpt":"Gâteau au chocolat maison moelleux au cacao, cuit dans un moule de 22 cm et nappé d'une ganache brillante. Pour 8 portions.","summary":"Ce gâteau au chocolat a une mie fine et moelleuse. On mélange séparément les ingrédients secs (farine, sucre, cacao, levure chimique) et les liquides (œufs, lait, huile, vanille), on les réunit au fouet et on cuit la pâte dans un moule de 22 cm. Il est nappé d'une ganache au chocolat et à la crème.\n\nIl demande 20 minutes de préparation, 45 de cuisson et 1 heure 25 de refroidissement et de repos. Pour 8 portions.","category":"Desserts","difficulty":"Facile","course":"Dessert","cuisine":"Internationale","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["gâteau au chocolat","recette gâteau au chocolat maison","gâteau au chocolat moelleux","gâteau au chocolat ganache","gâteau au cacao","comment faire un gâteau au chocolat","cake au chocolat"],"ingredients":[{"name":"farine de blé","amount":"200","unit":"g","group":"Pour le gâteau"},{"name":"sucre","amount":"200","unit":"g","group":"Pour le gâteau"},{"name":"cacao en poudre non sucré","amount":"60","unit":"g","group":"Pour le gâteau"},{"name":"levure chimique","amount":"2","unit":"cuillère à café","group":"Pour le gâteau"},{"name":"sel","amount":"1","unit":"pincée","group":"Pour le gâteau"},{"name":"gros œufs","amount":"3","unit":"","group":"Pour le gâteau"},{"name":"lait entier","amount":"240","unit":"ml","group":"Pour le gâteau"},{"name":"huile végétale","amount":"120","unit":"ml","group":"Pour le gâteau"},{"name":"extrait de vanille","amount":"1","unit":"cuillère à café","group":"Pour le gâteau"},{"name":"beurre (pour le moule)","amount":"10","unit":"g","group":"Pour le gâteau"},{"name":"chocolat mi-amer","amount":"150","unit":"g","group":"Pour le nappage"},{"name":"crème liquide entière","amount":"150","unit":"ml","group":"Pour le nappage"}],"steps":[{"title":"Préparer les ingrédients","content":"Prévoir 200 g de farine, 200 g de sucre, 60 g de cacao, 2 cuillères à café de levure, 3 œufs, 240 ml de lait, 120 ml d'huile, 1 cuillère à café de vanille, 150 g de chocolat et 150 ml de crème. Préchauffer le four à 180 °C, beurrer un moule rond de 22 cm et le fariner avec un peu de la farine, en retirant l'excès.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Gâteau au chocolat avec ganache: Préparer les ingrédients"},{"title":"Mélanger les ingrédients secs","content":"Tamiser dans un grand saladier les 200 g de farine, les 200 g de sucre, les 60 g de cacao, la levure et une pincée de sel. Mélanger au fouet.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Gâteau au chocolat avec ganache: Mélanger les ingrédients secs"},{"title":"Fouetter les liquides","content":"Dans un autre saladier, fouetter 3 œufs avec 240 ml de lait, 120 ml d'huile et 1 cuillère à café de vanille pendant 1 minute, jusqu'à ce que le mélange soit homogène.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Gâteau au chocolat avec ganache: Fouetter les liquides"},{"title":"Réunir les deux mélanges","content":"Verser les liquides sur les ingrédients secs et fouetter jusqu'à obtenir une pâte lisse, fluide et sans grumeaux. Ne pas trop mélanger pour que le gâteau ne devienne pas dur.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Gâteau au chocolat avec ganache: Réunir les deux mélanges"},{"title":"Remplir le moule","content":"Verser la pâte dans le moule préparé, la lisser à la spatule et taper doucement le moule sur le plan de travail pour chasser les grosses bulles.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Gâteau au chocolat avec ganache: Remplir le moule"},{"title":"Cuire le gâteau","content":"Cuire à 180 °C de 35 à 40 minutes, jusqu'à ce qu'un pic en bois planté au centre ressorte propre ou avec quelques miettes humides. Ne pas ouvrir le four pendant les 25 premières minutes.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Gâteau au chocolat avec ganache: Cuire le gâteau"},{"title":"Laisser refroidir et démouler","content":"Laisser le gâteau 10 minutes dans le moule, le démouler sur une grille et le laisser refroidir complètement, au moins 1 heure.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Gâteau au chocolat avec ganache: Laisser refroidir et démouler"},{"title":"Napper et servir","content":"Chauffer 150 ml de crème jusqu'aux premiers frémissements et la verser sur 150 g de chocolat haché. Attendre 2 minutes et mélanger jusqu'à ce que la ganache soit brillante. La laisser tiédir 10 minutes, la verser sur le gâteau froid et laisser prendre 15 minutes avant de couper.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Gâteau au chocolat avec ganache: Napper et servir"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Gâteau au chocolat avec ganache"}],"notes":"Peser les ingrédients : un peu trop de farine rend le gâteau sec. Tamiser le cacao pour éviter les grumeaux. La pâte est liquide ; c'est normal et c'est ce qui donne une mie moelleuse. Chaque four est différent : commencer à vérifier à 35 minutes. Si la ganache épaissit trop, la réchauffer 10 secondes au micro-ondes. Contient gluten, œuf et lait. Il se conserve 3 jours couvert à température ambiante ou 5 jours au réfrigérateur ; le sortir 20 minutes avant de servir.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 portion (1/8 du gâteau, environ 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 8 portions : 200 g de farine, 200 g de sucre, 60 g de cacao, 9 g de levure, 0,4 g de sel, 150 g d'œuf, 245 g de lait entier, 110 g d'huile de soja, 4 g de vanille, 10 g de beurre (tout est compté même si une partie reste dans le moule), 150 g de chocolat mi-amer et 143 g de crème.","note":"Estimation par portion. Varie selon la taille de la part et la marque de chocolat."},"seo":{"title":"Gâteau au chocolat moelleux avec ganache, maison | Manual de Cocina","description":"Gâteau au chocolat maison : biscuit moelleux au cacao dans un moule de 22 cm, nappé de ganache brillante. Pour 8 portions. Pas à pas en photos.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Pourquoi la pâte est-elle aussi liquide ?","a":"Elle contient plus de liquide qu'une pâte à gâteau classique : le lait et l'huile donnent une mie moelleuse. C'est normal et elle se fixe à la cuisson."},{"q":"Comment savoir si le gâteau est cuit ?","a":"Planter un pic en bois au centre : il doit ressortir propre ou avec quelques miettes humides, pas avec de la pâte crue. La surface doit revenir quand on appuie doucement."},{"q":"Peut-on le faire sans ganache ?","a":"Oui. On peut le servir nature ou saupoudré de sucre glace. La ganache apporte du moelleux et de la brillance, mais le gâteau est bon sans elle."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"76d8661f-9a9d-5bbc-9eb3-f6df8eef5569","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"it","slug":"torta-al-cioccolato-con-ganache","public_path":"/it/torta-al-cioccolato-con-ganache","source_url":null,"title":"Torta al cioccolato con ganache","excerpt":"Torta al cioccolato fatta in casa, soffice e umida, con cacao, cotta in uno stampo da 22 cm e ricoperta di ganache lucida. Per 8 porzioni.","summary":"Questa torta al cioccolato ha una mollica fine e umida. Si mescolano separatamente gli ingredienti secchi (farina, zucchero, cacao, lievito) e quelli liquidi (uova, latte, olio, vaniglia), si uniscono con la frusta e si cuoce l'impasto in uno stampo da 22 cm. Si ricopre con una ganache di cioccolato e panna.\n\nRichiede 20 minuti di preparazione, 45 di cottura e 1 ora e 25 di raffreddamento e riposo. Per 8 porzioni.","category":"Dolci","difficulty":"Facile","course":"Dolce","cuisine":"Internazionale","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["torta al cioccolato","ricetta torta al cioccolato fatta in casa","torta al cioccolato umida","torta al cioccolato con ganache","torta al cacao","come fare la torta al cioccolato","dolce al cioccolato"],"ingredients":[{"name":"farina 00","amount":"200","unit":"g","group":"Per la torta"},{"name":"zucchero","amount":"200","unit":"g","group":"Per la torta"},{"name":"cacao amaro in polvere","amount":"60","unit":"g","group":"Per la torta"},{"name":"lievito in polvere per dolci","amount":"2","unit":"cucchiaino","group":"Per la torta"},{"name":"sale","amount":"1","unit":"pizzico","group":"Per la torta"},{"name":"uova grandi","amount":"3","unit":"","group":"Per la torta"},{"name":"latte intero","amount":"240","unit":"ml","group":"Per la torta"},{"name":"olio di semi","amount":"120","unit":"ml","group":"Per la torta"},{"name":"estratto di vaniglia","amount":"1","unit":"cucchiaino","group":"Per la torta"},{"name":"burro (per lo stampo)","amount":"10","unit":"g","group":"Per la torta"},{"name":"cioccolato fondente","amount":"150","unit":"g","group":"Per la copertura"},{"name":"panna fresca","amount":"150","unit":"ml","group":"Per la copertura"}],"steps":[{"title":"Prepara gli ingredienti","content":"Tieni pronti 200 g di farina, 200 g di zucchero, 60 g di cacao, 2 cucchiaini di lievito, 3 uova, 240 ml di latte, 120 ml di olio, 1 cucchiaino di vaniglia, 150 g di cioccolato e 150 ml di panna. Preriscalda il forno a 180 °C, imburra uno stampo rotondo da 22 cm e infarinalo con un po' di farina, eliminando l'eccesso.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Torta al cioccolato con ganache: Prepara gli ingredienti"},{"title":"Mescola gli ingredienti secchi","content":"Setaccia in una ciotola grande i 200 g di farina, i 200 g di zucchero, i 60 g di cacao, il lievito e un pizzico di sale. Mescola con la frusta.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Torta al cioccolato con ganache: Mescola gli ingredienti secchi"},{"title":"Sbatti i liquidi","content":"In un'altra ciotola sbatti 3 uova con 240 ml di latte, 120 ml di olio e 1 cucchiaino di vaniglia per 1 minuto, finché il composto è omogeneo.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Torta al cioccolato con ganache: Sbatti i liquidi"},{"title":"Unisci i due composti","content":"Versa i liquidi sugli ingredienti secchi e sbatti fino a ottenere un impasto liscio, fluido e senza grumi. Non lavorarlo troppo, perché la torta non diventi dura.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Torta al cioccolato con ganache: Unisci i due composti"},{"title":"Riempi lo stampo","content":"Versa l'impasto nello stampo preparato, livellalo con una spatola e batti delicatamente lo stampo sul piano per eliminare le bolle d'aria grandi.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Torta al cioccolato con ganache: Riempi lo stampo"},{"title":"Cuoci la torta","content":"Cuoci a 180 °C per 35-40 minuti, finché uno stecchino infilato al centro esce pulito o con qualche briciola umida. Non aprire il forno nei primi 25 minuti.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Torta al cioccolato con ganache: Cuoci la torta"},{"title":"Raffredda e sforma","content":"Lascia la torta 10 minuti nello stampo, sformala su una griglia e lasciala raffreddare completamente, almeno 1 ora.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Torta al cioccolato con ganache: Raffredda e sforma"},{"title":"Ricopri e servi","content":"Scalda 150 ml di panna fino a quando inizia a bollire e versala su 150 g di cioccolato tritato. Aspetta 2 minuti e mescola fino a ottenere una ganache lucida. Lasciala intiepidire 10 minuti, versala sulla torta fredda e lasciala rapprendere 15 minuti prima di tagliarla.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Torta al cioccolato con ganache: Ricopri e servi"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Torta al cioccolato con ganache"}],"notes":"Pesa gli ingredienti: un po' di farina in più rende la torta asciutta. Setaccia il cacao per evitare grumi. L'impasto è liquido; è normale e dà una mollica umida. Ogni forno è diverso: inizia a controllare a 35 minuti. Se la ganache si addensa troppo, scaldala 10 secondi nel microonde. Contiene glutine, uova e latte. Si conserva 3 giorni coperta a temperatura ambiente o 5 in frigorifero; toglila dal frigo 20 minuti prima di servirla.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 porzione (1/8 della torta, circa 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 8 porzioni: 200 g di farina, 200 g di zucchero, 60 g di cacao, 9 g di lievito, 0,4 g di sale, 150 g di uovo, 245 g di latte intero, 110 g di olio di soia, 4 g di vaniglia, 10 g di burro (si conta tutto anche se una parte resta nello stampo), 150 g di cioccolato fondente e 143 g di panna.","note":"Stima per porzione. Varia con la dimensione della fetta e la marca del cioccolato."},"seo":{"title":"Torta al cioccolato umida con ganache, fatta in casa | Manual de Cocina","description":"Torta al cioccolato fatta in casa: soffice e umida, cotta in stampo da 22 cm e ricoperta di ganache lucida. Per 8 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Perché l'impasto è così liquido?","a":"Contiene più liquidi di un normale impasto per torte: latte e olio danno una mollica umida. È normale e si rassoda in cottura."},{"q":"Come capisco che la torta è cotta?","a":"Infila uno stecchino al centro: deve uscire pulito o con qualche briciola umida, non con impasto crudo. La superficie deve tornare su se premuta delicatamente."},{"q":"Si può fare senza ganache?","a":"Sì. Puoi servirla al naturale o con zucchero a velo. La ganache dà umidità e lucentezza, ma la torta è buona anche senza."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f55abeb9-8391-5fd2-b261-c223b19dcf98","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"ja","slug":"チョコレートケーキ","public_path":"/ja/チョコレートケーキ","source_url":null,"title":"チョコレートケーキ（ガナッシュがけ）","excerpt":"ココアで作るしっとりした手作りチョコレートケーキ。直径22cmの型で焼き、つやのあるガナッシュをかけます。8人分です。","summary":"このチョコレートケーキは、きめ細かくしっとりした生地です。粉類（小麦粉、砂糖、ココア、ベーキングパウダー）と液体（卵、牛乳、油、バニラ）を別々に混ぜ、泡立て器で合わせて、直径22cmの型で焼きます。仕上げにチョコレートと生クリームのガナッシュをかけます。\n\n下ごしらえ20分、焼き時間45分、冷ます・休ませる時間が1時間25分です。8人分です。","category":"デザート","difficulty":"簡単","course":"デザート","cuisine":"インターナショナル","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["チョコレートケーキ","チョコレートケーキ 作り方","しっとり チョコレートケーキ","ガナッシュ チョコレートケーキ","ココアケーキ","チョコケーキ 手作り","混ぜて焼くだけ ケーキ"],"ingredients":[{"name":"薄力粉","amount":"200","unit":"g","group":"ケーキ用"},{"name":"砂糖","amount":"200","unit":"g","group":"ケーキ用"},{"name":"無糖ココアパウダー","amount":"60","unit":"g","group":"ケーキ用"},{"name":"ベーキングパウダー","amount":"2","unit":"小さじ","group":"ケーキ用"},{"name":"塩","amount":"1","unit":"ひとつまみ","group":"ケーキ用"},{"name":"卵（Lサイズ）","amount":"3","unit":"","group":"ケーキ用"},{"name":"牛乳","amount":"240","unit":"ml","group":"ケーキ用"},{"name":"植物油","amount":"120","unit":"ml","group":"ケーキ用"},{"name":"バニラエクストラクト","amount":"1","unit":"小さじ","group":"ケーキ用"},{"name":"バター（型用）","amount":"10","unit":"g","group":"ケーキ用"},{"name":"セミスイートチョコレート","amount":"150","unit":"g","group":"かける用"},{"name":"生クリーム","amount":"150","unit":"ml","group":"かける用"}],"steps":[{"title":"材料を準備する","content":"薄力粉200g、砂糖200g、ココア60g、ベーキングパウダー小さじ2、卵3個、牛乳240ml、油120ml、バニラ小さじ1、チョコレート150g、生クリーム150mlを用意します。オーブンを180°Cに予熱し、直径22cmの丸型にバターを塗り、薄力粉を少しふって余分をはらいます。","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 材料を準備する"},{"title":"粉類を混ぜる","content":"大きめのボウルに薄力粉200g、砂糖200g、ココア60g、ベーキングパウダー、塩ひとつまみをふるい入れ、泡立て器で混ぜます。","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 粉類を混ぜる"},{"title":"液体を混ぜる","content":"別のボウルに卵3個、牛乳240ml、油120ml、バニラ小さじ1を入れ、均一になるまで1分ほど泡立て器で混ぜます。","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 液体を混ぜる"},{"title":"2つを合わせる","content":"粉類に液体を注ぎ、なめらかで流れるような、ダマのない生地になるまで混ぜます。混ぜすぎるとかたくなるので注意します。","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 2つを合わせる"},{"title":"型に入れる","content":"生地を用意した型に流し入れ、ゴムベラで平らにならし、型を軽く台に打ちつけて大きな気泡を抜きます。","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 型に入れる"},{"title":"焼く","content":"180°Cで35〜40分、中心に竹串を刺してなにもつかないか、しっとりしたかすがつく程度になるまで焼きます。最初の25分はオーブンを開けないでください。","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 焼く"},{"title":"冷まして型から外す","content":"型のまま10分おいてから網にひっくり返して出し、完全に冷まします。1時間以上かかります。","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: 冷まして型から外す"},{"title":"ガナッシュをかけて食べる","content":"生クリーム150mlをふつふつするまで温め、刻んだチョコレート150gにかけます。2分おいてからつやが出るまで混ぜます。10分ほど冷ましてから、冷めたケーキにかけ、15分おいて固めてから切り分けます。","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"チョコレートケーキ（ガナッシュがけ）: ガナッシュをかけて食べる"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"チョコレートケーキ（ガナッシュがけ）"}],"notes":"材料は計量器ではかります。粉が少し多いだけでもパサつきます。ココアはふるってダマを防ぎます。生地はゆるめですが、それでよく、しっとり仕上がります。オーブンによって焼き時間が違うので、35分から確認してください。ガナッシュがかたくなりすぎたら、電子レンジで10秒温めます。小麦、卵、乳を含みます。ラップをして常温で3日、冷蔵庫で5日保存でき、食べる20分前に出します。","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1人分（ケーキの8分の1、約120g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、8人分で割って合計しています。小麦粉200g、砂糖200g、ココア60g、ベーキングパウダー9g、塩0.4g、卵150g、牛乳245g、大豆油110g、バニラ4g、バター10g（一部が型に残りますが全量を計算）、チョコレート150g、生クリーム143gを使用しています。","note":"1人分の目安です。切り分けの大きさやチョコレートの種類で変わります。"},"seo":{"title":"しっとりチョコレートケーキの作り方｜ガナッシュがけ | Manual de Cocina","description":"ココアで作るしっとり手作りチョコレートケーキ。直径22cmの型で焼き、つやのあるガナッシュをかけます。8人分。作り方を写真付きで解説します。","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"生地がゆるいのはなぜですか？","a":"普通のケーキ生地より液体が多いためです。牛乳と油でしっとり仕上がります。ゆるいのは普通で、焼くと固まります。"},{"q":"焼き上がりはどう確かめますか？","a":"中心に竹串を刺し、なにもつかないか、しっとりしたかすがつく程度なら焼き上がりです。生の生地がつく場合はもう少し焼きます。表面を軽く押して戻れば大丈夫です。"},{"q":"ガナッシュなしでも作れますか？","a":"作れます。そのままでも、粉砂糖をふっても食べられます。ガナッシュはしっとり感とつやを足しますが、なくてもおいしいです。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"76f88660-8b37-5348-8b49-bef908018060","recipe_group_id":"4d174ec8-39c2-49d8-824d-99d58cc3d470","language":"pt","slug":"bolo-de-chocolate-com-cobertura","public_path":"/pt/bolo-de-chocolate-com-cobertura","source_url":null,"title":"Bolo de chocolate com cobertura de ganache","excerpt":"Bolo de chocolate caseiro, úmido e fofinho, com cacau, assado em forma de 22 cm e coberto com ganache brilhante. Rende 8 porções.","summary":"Este bolo de chocolate tem miolo fino e úmido. Os ingredientes secos (farinha, açúcar, cacau e fermento) e os líquidos (ovos, leite, óleo e baunilha) são misturados separadamente, unidos com um fouet e assados em uma forma de 22 cm. A cobertura é uma ganache de chocolate e creme de leite.\n\nLeva 20 minutos de preparo, 45 de forno e 1 hora e 25 para esfriar e descansar. Rende 8 porções.","category":"Sobremesas","difficulty":"Fácil","course":"Sobremesa","cuisine":"Internacional","prep_time_minutes":20,"cook_time_minutes":45,"total_time_minutes":150,"servings":8,"keywords":["bolo de chocolate","receita de bolo de chocolate caseiro","bolo de chocolate úmido","bolo de chocolate com ganache","bolo de cacau","como fazer bolo de chocolate","bolo de chocolate fofinho"],"ingredients":[{"name":"farinha de trigo","amount":"200","unit":"g","group":"Para o bolo"},{"name":"açúcar","amount":"200","unit":"g","group":"Para o bolo"},{"name":"cacau em pó sem açúcar","amount":"60","unit":"g","group":"Para o bolo"},{"name":"fermento em pó","amount":"2","unit":"colher de chá","group":"Para o bolo"},{"name":"sal","amount":"1","unit":"pitada","group":"Para o bolo"},{"name":"ovos grandes","amount":"3","unit":"","group":"Para o bolo"},{"name":"leite integral","amount":"240","unit":"ml","group":"Para o bolo"},{"name":"óleo vegetal","amount":"120","unit":"ml","group":"Para o bolo"},{"name":"extrato de baunilha","amount":"1","unit":"colher de chá","group":"Para o bolo"},{"name":"manteiga (para a forma)","amount":"10","unit":"g","group":"Para o bolo"},{"name":"chocolate meio amargo","amount":"150","unit":"g","group":"Para a cobertura"},{"name":"creme de leite fresco","amount":"150","unit":"ml","group":"Para a cobertura"}],"steps":[{"title":"Separe os ingredientes","content":"Tenha à mão 200 g de farinha, 200 g de açúcar, 60 g de cacau, 2 colheres de chá de fermento, 3 ovos, 240 ml de leite, 120 ml de óleo, 1 colher de chá de baunilha, 150 g de chocolate e 150 ml de creme de leite. Preaqueça o forno a 180 °C, unte uma forma redonda de 22 cm com manteiga e polvilhe com um pouco da farinha, sacudindo o excesso.","image_url":"/recetas/torta-de-chocolate/paso-01.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Separe os ingredientes"},{"title":"Misture os ingredientes secos","content":"Peneire em uma tigela grande os 200 g de farinha, os 200 g de açúcar, os 60 g de cacau, o fermento e uma pitada de sal. Misture com um fouet.","image_url":"/recetas/torta-de-chocolate/paso-02.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Misture os ingredientes secos"},{"title":"Bata os líquidos","content":"Em outra tigela, bata 3 ovos com 240 ml de leite, 120 ml de óleo e 1 colher de chá de baunilha por 1 minuto, até ficar uniforme.","image_url":"/recetas/torta-de-chocolate/paso-03.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Bata os líquidos"},{"title":"Una as duas misturas","content":"Despeje os líquidos sobre os ingredientes secos e bata até obter uma massa lisa, fluida e sem grumos. Não bata demais, para o bolo não ficar duro.","image_url":"/recetas/torta-de-chocolate/paso-04.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Una as duas misturas"},{"title":"Encha a forma","content":"Passe a massa para a forma preparada, nivele com uma espátula e bata a forma de leve na bancada para eliminar as bolhas grandes.","image_url":"/recetas/torta-de-chocolate/paso-05.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Encha a forma"},{"title":"Asse o bolo","content":"Asse a 180 °C por 35 a 40 minutos, até um palito espetado no centro sair limpo ou com algumas migalhas úmidas. Não abra o forno nos primeiros 25 minutos.","image_url":"/recetas/torta-de-chocolate/paso-06.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Asse o bolo"},{"title":"Esfrie e desenforme","content":"Deixe o bolo 10 minutos na forma, desenforme sobre uma grade e deixe esfriar por completo, por pelo menos 1 hora.","image_url":"/recetas/torta-de-chocolate/paso-07.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Esfrie e desenforme"},{"title":"Cubra e sirva","content":"Aqueça 150 ml de creme de leite até começar a ferver e despeje sobre 150 g de chocolate picado. Espere 2 minutos e misture até ficar brilhante. Deixe amornar por 10 minutos, despeje a ganache sobre o bolo frio e deixe firmar por 15 minutos antes de cortar.","image_url":"/recetas/torta-de-chocolate/paso-08.webp","image_alt":"Bolo de chocolate com cobertura de ganache: Cubra e sirva"}],"image_url":"/recetas/torta-de-chocolate/portada.webp","gallery":[{"url":"/recetas/torta-de-chocolate/portada.webp","alt":"Bolo de chocolate com cobertura de ganache"}],"notes":"Pese os ingredientes: um pouco de farinha a mais deixa o bolo seco. Peneire o cacau para não ficar com grumos. A massa fica líquida; é normal e dá um miolo úmido. Cada forno é diferente: comece a verificar aos 35 minutos. Se a ganache engrossar demais, aqueça por 10 segundos no micro-ondas. Contém glúten, ovo e leite. Dura 3 dias coberto em temperatura ambiente ou 5 na geladeira; tire 20 minutos antes de servir.","nutrition":{"calories":546,"protein_g":8.8,"carbs_g":62,"fat_g":31.1,"sodium_mg":199,"serving_size":"1 porção (1/8 do bolo, cerca de 120 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 8 porções: 200 g de farinha, 200 g de açúcar, 60 g de cacau, 9 g de fermento, 0,4 g de sal, 150 g de ovo, 245 g de leite integral, 110 g de óleo de soja, 4 g de baunilha, 10 g de manteiga (tudo é contado, mesmo que parte fique na forma), 150 g de chocolate meio amargo e 143 g de creme de leite.","note":"Estimativa por porção. Varia com o tamanho da fatia e a marca do chocolate."},"seo":{"title":"Bolo de chocolate úmido com ganache, caseiro | Manual de Cocina","description":"Bolo de chocolate caseiro: massa úmida de cacau, assada em forma de 22 cm e coberta com ganache brilhante. Rende 8 porções. Passo a passo com fotos.","image_variants":["/recetas/torta-de-chocolate/portada-1x1.webp","/recetas/torta-de-chocolate/portada-4x3.webp","/recetas/torta-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Por que a massa do bolo fica tão líquida?","a":"Porque leva mais líquido que uma massa de bolo comum: o leite e o óleo dão um miolo úmido. É normal e firma ao assar."},{"q":"Como sei que o bolo está pronto?","a":"Espete um palito no centro: deve sair limpo ou com algumas migalhas úmidas, não com massa crua. A superfície deve voltar ao pressionar de leve."},{"q":"Posso fazer sem a ganache?","a":"Pode. Sirva puro ou polvilhado com açúcar de confeiteiro. A ganache dá umidade e brilho, mas o bolo é bom sem ela."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/torta-de-chocolate') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
